  input: process.stdin,
  output: process.stdout
});
​
let input = [];
rl.on('line', (line) => {
  input.push(line.trim());
​
  if (input.length === 2 * parseInt(input[0]) + 1) {
    let n = parseInt(input[0]);
    let res = 0;
    let isOrder = true;
    let count = 0;
​
    for (let i = 1; i <= 2 * n; i++) {
      let s = input[i];
