package main
​
import (
    "bufio"
    "fmt"
    "os"
    "strings"
)
​
func main() {
    // 读取输入
    reader := bufio.NewReader(os.Stdin)
​
    var n int
    fmt.Scan(&n) // 读取整数 n
​
    res := 0
    isOrder := true
    count := 0
​
    // 读取 2n 行指令
    for i := 0; i < 2*n; i++ {
        s, _ := reader.ReadString('\n')
        s = strings.TrimSpace(s)
​
        if strings.Contains(s, "remove") {
            // 只在移除的时候进行调整
            if !isOrder {
                res++
            }
            isOrder = true
            count--
        } else if strings.Contains(s, "tail") {
            count++
        } else {
            // 添加在头部会导致移除时乱序
            if count > 0 {
                isOrder = false
            }
            count++
        }
    }
​
    fmt.Println(res)
}
